package com.weearntogether.play

import android.app.Activity
import android.content.Intent
import android.graphics.Color
import android.graphics.Typeface
import android.graphics.drawable.GradientDrawable
import android.os.Bundle
import android.view.Gravity
import com.weearntogether.lazygarden.LazyGardenActivity
import android.widget.*
import java.text.SimpleDateFormat
import java.util.*

/** Premium discovery home using only WET artwork/components. */
class PremiumHomeActivity : Activity() {
    private val navy=0xff07152f.toInt(); private val blue=0xff3978f6.toInt(); private val purple=0xff713fe8.toInt(); private val ink=0xff202432.toInt(); private val muted=0xff697386.toInt(); private val gold=0xffffc857.toInt()
    private lateinit var ads:NativeGameAds;private lateinit var root:LinearLayout; private lateinit var host:FrameLayout; private lateinit var rewardButton:Button; private lateinit var coinText:TextView
    private val loyalty by lazy { LoyaltyProgress(this) }; private val accounts by lazy { AccountStore(this) }
    private fun dp(v:Int)=(v*resources.displayMetrics.density).toInt()
    private fun round(color:Int,r:Int=22)=GradientDrawable().apply{setColor(color);cornerRadius=dp(r).toFloat()}
    private fun premiumGradient(r:Int=22)=GradientDrawable(GradientDrawable.Orientation.TL_BR,intArrayOf(navy,purple,blue)).apply{cornerRadius=dp(r).toFloat()}
    private fun text(s:String,size:Int,color:Int=ink,bold:Boolean=false)=TextView(this).apply{text=s;textSize=size.toFloat();setTextColor(color);if(bold)setTypeface(null,Typeface.BOLD)}
    override fun onCreate(state:Bundle?){super.onCreate(state);window.statusBarColor=navy;window.navigationBarColor=navy
        if(!accounts.isSignedIn()&&!(BuildConfig.DEBUG&&intent.getBooleanExtra("native_qa",false))){startActivity(Intent(this,MainActivity::class.java));finish();return}
        ads=NativeGameAds(this,"home");build();rewardButton.isEnabled=true
    }
    private fun build(){host=FrameLayout(this).apply{setBackgroundColor(0xfff5f7ff.toInt())};val scroll=ScrollView(this).apply{isFillViewport=true;clipToPadding=false};root=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(16),0,dp(16),dp(108))};scroll.addView(root);host.addView(scroll,FrameLayout.LayoutParams(-1,-1));setContentView(host);host.setOnApplyWindowInsetsListener{v,i->v.setPadding(i.systemWindowInsetLeft,i.systemWindowInsetTop,i.systemWindowInsetRight,i.systemWindowInsetBottom);i};host.requestApplyInsets();header();premiumHero();dailyGame();sectionTitle("★","Lojërat tona premium","Native HD 2D");nativeSpotlight();rewardCard();sectionTitle("🔥","Më të luajturat","Të gjitha");gameRow();sectionTitle("✦","Eksploro lojërat","Më shumë");compactGames();bottomNav()}
    private fun header(){val h=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(18),dp(12),dp(16),dp(14));background=premiumGradient(0);minimumHeight=dp(82)};val portrait=PlayerPortrait.image(this).apply{setOnClickListener{PlayerPortrait.pick(this@PremiumHomeActivity)}};h.addView(portrait,LinearLayout.LayoutParams(dp(48),dp(48)).apply{rightMargin=dp(12)});val identity=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};identity.addView(text("WE EARN TOGETHER",11,gold,true));identity.addView(text(accounts.currentName()?:"Lojtari",20,Color.WHITE,true));h.addView(identity,LinearLayout.LayoutParams(0,-2,1f));coinText=text("★ ${loyalty.points}",16,gold,true).apply{gravity=Gravity.CENTER;background=round(0x33202a55,18);setPadding(dp(12),dp(8),dp(12),dp(8))};h.addView(coinText);root.addView(h,LinearLayout.LayoutParams(-1,-2).apply{leftMargin=-dp(16);rightMargin=-dp(16);bottomMargin=dp(14)})}
    private fun premiumHero(){val hero=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(20),dp(18),dp(20),dp(18));background=premiumGradient(24);elevation=dp(5).toFloat()};hero.addView(text("PREMIUM PLAY STUDIO",12,gold,true));hero.addView(text("Luaj. Përparo. Ruaje progresin.",25,Color.WHITE,true).apply{setPadding(0,dp(7),0,dp(5))});hero.addView(text("Block Puzzle, Bubble Shooter, Knife Hit dhe lojëra të tjera native — nivele, vështirësi dhe progres i ruajtur.",14,0xffdce5ff.toInt()));root.addView(hero,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(14)})}
    private data class Daily(val key:String,val title:String,val subtitle:String,val go:()->Unit)
    private fun dailyGame(){val games=listOf(
        Daily("block","BLOCK PUZZLE","Magic levels • combo • 250 nivele"){startActivity(Intent(this,BlockPuzzleActivity::class.java))},
        Daily("bubble","BUBBLE SHOOTER","Aim • bank shots • 250 nivele"){startActivity(Intent(this,BubbleShooterActivity::class.java))},
        Daily("knife","KNIFE HIT","Arcade • boss • 200 nivele"){startActivity(Intent(this,KnifeHitActivity::class.java))},
        Daily("garden","LAZYGARDEN","Match-3 • histori • restaurim"){startActivity(Intent(this,LazyGardenActivity::class.java))},
        Daily("balls","BALL SORT","Puzzle • vështirësi progresive"){startActivity(Intent(this,BallSortActivity::class.java))}
    );val day=SimpleDateFormat("yyyyMMdd",Locale.US).format(Date()).toIntOrNull()?:0;val g=games[Math.floorMod(day,games.size)];val card=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(10),dp(10),dp(12),dp(10));background=round(0xff101c45.toInt(),20);elevation=dp(4).toFloat();setOnClickListener{g.go()}};card.addView(StudioArtwork(this,g.key).apply{background=premiumGradient(14);clipToOutline=true},LinearLayout.LayoutParams(dp(104),dp(104)).apply{rightMargin=dp(14)});val words=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};words.addView(text("LOJA E DITËS",11,gold,true));words.addView(text(g.title,20,Color.WHITE,true).apply{setPadding(0,dp(3),0,dp(3))});words.addView(text(g.subtitle,12,0xffcbd8ff.toInt()));words.addView(text("LUAJ TANI  ›",13,gold,true).apply{setPadding(0,dp(8),0,0)});card.addView(words,LinearLayout.LayoutParams(0,-2,1f));root.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(16)})}
    private fun sectionTitle(icon:String,title:String,more:String){val r=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};r.addView(text("$icon  $title",20,ink,true),LinearLayout.LayoutParams(0,-2,1f));r.addView(text(more,11,purple,true));root.addView(r,LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(8);bottomMargin=dp(12)})}
    private fun nativeSpotlight(){val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};spotlight(row,"block","BLOCK PUZZLE","250 nivele"){startActivity(Intent(this@PremiumHomeActivity,BlockPuzzleActivity::class.java))};spotlight(row,"bubble","BUBBLE SHOOTER","250 nivele"){startActivity(Intent(this@PremiumHomeActivity,BubbleShooterActivity::class.java))};root.addView(row,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(16)})}
    private fun spotlight(row:LinearLayout,key:String,title:String,sub:String,go:()->Unit){val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(7),dp(7),dp(7),dp(10));background=premiumGradient(20);elevation=dp(4).toFloat();setOnClickListener{go()}};c.addView(StudioArtwork(this,key).apply{background=round(0x22ffffff,14);clipToOutline=true},LinearLayout.LayoutParams(-1,dp(126)));c.addView(text(title,15,Color.WHITE,true).apply{setPadding(dp(5),dp(9),0,0)});c.addView(text(sub,11,gold,true).apply{setPadding(dp(5),dp(2),0,0)});row.addView(c,LinearLayout.LayoutParams(0,-2,1f).apply{rightMargin=dp(7);leftMargin=dp(2)})}
    private fun rewardCard(){val card=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(14),dp(12),dp(14),dp(10));background=round(0xfffff8e8.toInt(),18)};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL};row.addView(text("★",30,gold,true),LinearLayout.LayoutParams(dp(42),-2));val words=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL};words.addView(text("Bonus me video",15,ink,true));words.addView(text("Vetëm pas verifikimit",12,muted));row.addView(words,LinearLayout.LayoutParams(0,-2,1f));rewardButton=Button(this).apply{text="Shiko";isAllCaps=false;textSize=14f;setTextColor(Color.WHITE);background=round(purple,14);setOnClickListener{showRewarded()}};row.addView(rewardButton,LinearLayout.LayoutParams(dp(82),dp(44)));card.addView(row);card.addView(text("Bonusi regjistrohet vetëm pas përfundimit dhe verifikimit të videos; nuk premtohet shpërblim monetar.",10,muted),LinearLayout.LayoutParams(-1,-2).apply{topMargin=dp(6)});root.addView(card,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(16)})}
    private fun gameRow(){val hsv=HorizontalScrollView(this).apply{isHorizontalScrollBarEnabled=false;clipToPadding=false};val row=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL};gameTile(row,"garden","LazyGarden"){startActivity(Intent(this,LazyGardenActivity::class.java))};gameTile(row,"block","Block Puzzle"){startActivity(Intent(this,BlockPuzzleActivity::class.java))};gameTile(row,"bubble","Bubble Shooter"){startActivity(Intent(this,BubbleShooterActivity::class.java))};gameTile(row,"knife","Knife Hit"){startActivity(Intent(this,KnifeHitActivity::class.java))};hsv.addView(row);root.addView(hsv,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(20)})}
    private fun gameTile(row:LinearLayout,key:String,title:String,go:()->Unit){val c=LinearLayout(this).apply{orientation=LinearLayout.VERTICAL;setPadding(dp(5),dp(5),dp(5),dp(8));background=round(Color.WHITE,18);elevation=dp(3).toFloat();setOnClickListener{go()}};c.addView(StudioArtwork(this,key).apply{background=premiumGradient(14);clipToOutline=true;contentDescription=title},LinearLayout.LayoutParams(-1,dp(168)));c.addView(text(title,17,ink,true).apply{setPadding(dp(8),dp(8),0,0)});c.addView(text("LUAJ  ›",13,purple,true).apply{setPadding(dp(8),dp(5),0,0)});row.addView(c,LinearLayout.LayoutParams(dp(166),dp(232)).apply{rightMargin=dp(12);bottomMargin=dp(7)})}
    private fun compactGames(){val ball=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(14),dp(12),dp(14),dp(12));background=round(0xffeef2ff.toInt(),18);setOnClickListener{startActivity(Intent(this@PremiumHomeActivity,BallSortActivity::class.java))}};ball.addView(BallSortCover(this),LinearLayout.LayoutParams(dp(72),dp(72)).apply{rightMargin=dp(14)});ball.addView(text("Ball Sort",19,ink,true),LinearLayout.LayoutParams(0,-2,1f));ball.addView(text("LUAJ ›",14,purple,true));root.addView(ball,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(10)});val names=listOf("2048" to "2048","word" to "Word Trails","memory" to "Memory Bloom","cups" to "Cup Shuffle","gamepix" to "GamePix");for((key,title) in names){val c=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER_VERTICAL;setPadding(dp(12),dp(9),dp(12),dp(9));background=round(Color.WHITE,16);setOnClickListener{when(key){"cups"->startActivity(Intent(this@PremiumHomeActivity,CupShuffleActivity::class.java));"gamepix"->startActivity(Intent(this@PremiumHomeActivity,GamePixActivity::class.java));else->startActivity(Intent(this@PremiumHomeActivity,Html5GamesActivity::class.java).putExtra("game",key))}}};c.addView(GameArtwork(this,key),LinearLayout.LayoutParams(dp(56),dp(56)).apply{rightMargin=dp(12)});c.addView(text(title,17,ink,true),LinearLayout.LayoutParams(0,-2,1f));c.addView(text("LUAJ ›",13,purple,true));root.addView(c,LinearLayout.LayoutParams(-1,-2).apply{bottomMargin=dp(9)})}}
    private fun bottomNav(){val bar=LinearLayout(this).apply{orientation=LinearLayout.HORIZONTAL;gravity=Gravity.CENTER;background=premiumGradient(26);elevation=dp(14).toFloat();setPadding(dp(8),dp(6),dp(8),dp(6))};fun nav(icon:String,label:String,go:()->Unit){val v=text("$icon\n$label",12,Color.WHITE,true).apply{gravity=Gravity.CENTER;setOnClickListener{go()}};bar.addView(v,LinearLayout.LayoutParams(0,dp(60),1f))};nav("◉","Lojëra"){};nav("♧","Oferta"){startActivity(Intent(this,AyetOfferwallActivity::class.java))};nav("▣","Portofoli"){startActivity(Intent(this,WalletActivity::class.java))};nav("☺","Profili"){startActivity(Intent(this,MainActivity::class.java).putExtra("open_profile",true))};host.addView(bar,FrameLayout.LayoutParams(-1,dp(78),Gravity.BOTTOM).apply{leftMargin=dp(10);rightMargin=dp(10);bottomMargin=dp(10)})}
    private fun showRewarded(){ads.rewarded(onGameplayReward={coinText.text="★ Në pritje";refreshBalance()})}
    private fun refreshBalance(){if(!accounts.isSignedIn()||!::coinText.isInitialized)return;CloudWorker.executor.execute{val balance=runCatching{BackendClient().request("getBalance",org.json.JSONObject().put("session_token",accounts.requireToken()))}.getOrNull();runOnUiThread{if(!isFinishing&&!isDestroyed&&balance!=null){val pending=balance.optLong("pending_coins");coinText.text="★ ${balance.optLong("verified_coins")}"+if(pending>0)" (+$pending)" else ""}}}}
    override fun onResume(){super.onResume();if(::ads.isInitialized)ads.resume();refreshBalance()}
    override fun onPause(){if(::ads.isInitialized)ads.pause();super.onPause()}
    override fun onDestroy(){if(::ads.isInitialized)ads.destroy();super.onDestroy()}
}
